with with_prev as (select *, lag(paid_at) over (partition by order_id order by paid_at, id) as prev_paid_at from payments), gaps as (select *, case when prev_paid_at is null or paid_at > prev_paid_at + interval 30 days then 1 else 0 end as new_group_flag from with_prev) select *, sum(new_group_flag) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as island_id from gaps;
